package com.gestourant.catalog;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=120) private String name; @Column(nullable=false,length=500) private String description; @Column(nullable=false,length=30) private String category; @Column(name="image_url",length=1000) private String imageUrl; @Column(nullable=false,precision=12,scale=2) private BigDecimal price; @Column(nullable=false) private Integer stock; @Column(nullable=false) private boolean active=true; protected Product(){} public Product(String n,String d,String c,BigDecimal p,Integer s){this(n,d,c,null,p,s);} public Product(String n,String d,String c,String imageUrl,BigDecimal p,Integer s){name=n;description=d;category=c;this.imageUrl=imageUrl;price=p;stock=s;} public Long getId(){return id;} public String getName(){return name;} public String getDescription(){return description;} public String getCategory(){return category;} public String getImageUrl(){return imageUrl;} public BigDecimal getPrice(){return price;} public Integer getStock(){return stock;} public boolean isActive(){return active;} public void update(String n,String d,String c,BigDecimal p,Integer s,boolean a){update(n,d,c,imageUrl,p,s,a);} public void update(String n,String d,String c,String imageUrl,BigDecimal p,Integer s,boolean a){name=n;description=d;category=c;this.imageUrl=imageUrl;price=p;stock=s;active=a;} public void reduceStock(int q){if(stock<q)throw new IllegalArgumentException("Inventario insuficiente para " + name);stock-=q;} public void restoreStock(int q){stock+=q;} }
